  for(final p in photos){keys(p,{'id','eventId','createdAt','mime','base64','sha256'});require(receiptIds.add(string(p['id'],80)) && ledger.containsKey(p['eventId']),'Invalid receipt association.');integer(p['createdAt'],0,4102444800000);final bytes=base64Decode(string(p['base64'],1500000));photoTotal+=bytes.length;require(bytes.length>=4 && bytes.length<=1024*1024 && bytes[bytes.length-2]==255 && bytes.last==217 && p['mime']=='image/jpeg' && attachmentMime(bytes)=='image/jpeg' && bytesHash(bytes)==p['sha256'] && base64Encode(bytes)==p['base64'],'Damaged original receipt.');}
