    for(final p in objects(c['products'])){require(products.add(id(p['id'])) && names.add(string(p['name'],120).toLowerCase()) && (p['name'] as String).trim().isNotEmpty,'Duplicate product.');final minimum=integer(p['minimum'],0,10000);integer(p['target'],minimum,10000);integer(p['packSize'],1,10000);integer(p['packCost']);string(p['supplier'],120);}
