  final docs=<String,Obj>{},lines=<String,Obj>{},invoices=<String>{};
  for(final d in objects(b['documents'])){require(!docs.containsKey(id(d['id'])) && ['purchase','expense'].contains(d['kind']),'Invalid document.');docs[d['id']]=d;string(d['supplier'],120);string(d['reference'],120);string(d['category'],80);string(d['note']);integer(d['recordedAt'],946684800000,4102444800000);if(d['date']!=null)integer(d['date'],946684800000,4102444800000);final amount=integer(d['amount']);integer(d['gst'],0,amount);
    if((d['reference'] as String).trim().isNotEmpty)require(invoices.add('${(d['supplier'] as String).trim().toLowerCase()}\n${(d['reference'] as String).trim().toLowerCase()}'),'Duplicate invoice.');
