  }
  final delivered=<String,int>{},deliveryEvents=<String>{},deliveryIds=<String>{};
  for(final d in objects(b['deliveries'])){final line=lines[d['lineId']],e=ledger[d['eventId']];require(deliveryIds.add(id(d['id'])) && deliveryEvents.add(d['eventId']) && line!=null && line['stock']==true && e!=null && e['type']=='restock' && e['quantity']==d['quantity'] && e['cost']==d['cost'] && time(e['timestamp'])==d['timestamp'] && time(e['recordedAt'])==d['recordedAt'],'Invalid delivery association.');if(!undone.contains(d['eventId']))delivered[d['lineId']]=(delivered[d['lineId']] ?? 0)+(d['quantity'] as int);}
