  final canceled=<String>{},cancelIds=<String>{};for(final c in objects(b['cancellations'])){require(cancelIds.add(id(c['id'])) && docs.containsKey(c['documentId']) && canceled.add(c['documentId']) && string(c['note']).trim().isNotEmpty,'Invalid document cancellation.');integer(c['recordedAt'],946684800000,4102444800000);}
  final auditIds=<String>{};for(final a in objects(b['audit'])){require(auditIds.add(string(a['id'])) && (a['eventId']==null || ledger.containsKey(a['eventId'])),'Invalid audit association.');string(a['action']);string(a['entityId']);integer(a['recordedAt'],946684800000,4102444800000);if(a['date']!=null)integer(a['date'],946684800000,4102444800000);obj(a['payload']);}
  if(b['finance']!=null){final f=obj(b['finance']);keys(f,{'settings','taxes'});final settings=obj(f['settings']);require(settings['gst'] is Map,'Missing GST settings.');for(final setting in settings.entries){final value=obj(setting.value);if(setting.key=='gst'){keys(value,{'registered','expenseCredits'});require(value['registered'] is bool && value['expenseCredits'] is bool,'Invalid GST settings.');}else{require(setting.key.startsWith('product:') && products.contains(setting.key.substring(8)) && ['taxable','gst_free','input_taxed'].contains(value['treatment']),'Invalid product tax setting.');}}
    final taxIds=<String>{};for(final t in objects(f['taxes'])){final tax=obj(t['tax']);keys(tax,{'registered','actualGst','inputGst','outputGst'});final actual=integer(tax['actualGst']),input=integer(tax['inputGst'],0,actual),output=integer(tax['outputGst']);require(taxIds.add(id(t['id'])) && tax['registered'] is bool && (tax['registered']==true || input==0 && output==0),'Invalid tax snapshot.');if(t['kind']=='ledger'){final e=ledger[t['id']];require(e!=null && actual<=e['cost'] && output<=e['revenue'] && (e['type']=='restock' || input==0),'Invalid ledger GST link.');}else{final d=docs[t['id']];require(t['kind']=='document' && d!=null && output==0 && actual<=d['amount'],'Invalid expense GST link.');}}
  }
  if(b['refunds']==null)return;
  final refunds=obj(b['refunds']);keys(refunds,{'requests','observations','returns'});final requests=<String,Obj>{};
  for(final r in objects(refunds['requests'])){final sale=ledger[r['saleId']];require(!requests.containsKey(id(r['id'])) && sale!=null && ['single','deal'].contains(sale['type']) && r['stripe'] is bool && (r['stripe']==true)==RegExp(r'^Stripe pi_[A-Za-z0-9]+ ·').hasMatch(sale['note']),'Invalid refund request.');integer(r['amount'],1,sale!['revenue']);integer(r['recordedAt'],946684800000,4102444800000);string(r['note']);requests[r['id']]=r;}
  final latest=<String,Obj>{},obsIds=<String>{},providers=<String,String>{};
  for(final o in objects(refunds['observations'])){final r=requests[o['requestId']];require(obsIds.add(id(o['id'])) && r!=null && ['pending','requires_action','succeeded','failed','canceled'].contains(o['status']),'Invalid refund observation.');integer(o['verifiedAt'],946684800000,4102444800000);if(o['created']!=null)integer(o['created'],946684800000,4102444800000);if(o['fee']!=null)integer(o['fee'],-10000000,10000000);string(o['failureReason']);final provider=string(o['providerId'],120);require(r!['stripe']==true?RegExp(r'^re_[A-Za-z0-9]+$').hasMatch(provider)&&o['created']!=null:provider=='manual-${r['id']}','Invalid provider link.');require(!providers.containsKey(provider)||providers[provider]==r['id'],'Refund linked twice.');providers[provider]=r['id'];final prior=latest[o['requestId']];if(prior!=null)require(o['verifiedAt']>=prior['verifiedAt'] && o['created']==prior['created'] && provider==prior['providerId'] && (prior['fee']==null || o['fee']!=null),'Invalid observation timeline.');latest[o['requestId']]=o;if(ledger[r['saleId']]!['payment']=='cash')require(o['fee']==null || o['fee']==0,'Cash refund fee must be zero.');}
  final sums=<String,int>{};for(final r in requests.values){final status=latest[r['id']]?['status'];if(!['failed','canceled'].contains(status)){sums[r['saleId']]=(sums[r['saleId']] ?? 0)+(r['amount'] as int);require(!undone.contains(r['saleId']),'Corrected sale has an active refund.');}}
