  final goods=<String,int>{},returnIds=<String>{},returnEvents=<String>{};for(final r in objects(refunds['returns'])){final request=requests[r['requestId']],e=ledger[r['eventId']];require(returnIds.add(id(r['id'])) && returnEvents.add(r['eventId']) && request!=null && e!=null && e['type']=='restock' && e['cost']==0 && e['quantity']==integer(r['quantity'],1,2) && time(e['recordedAt'])==r['recordedAt'],'Invalid goods return.');if(!undone.contains(r['eventId']))goods[request!['saleId']]=(goods[request['saleId']] ?? 0)+(r['quantity'] as int);}
  for(final q in goods.entries){require(q.value<=ledger[q.key]!['quantity'] && !undone.contains(q.key),'Returned quantity exceeds original sale.');}
}
